  ('GMRC', 4, 'G4-001', 'Naisasabuhay ang pagpapahalaga sa sarili sa pamamagitan ng pagbibigay-halaga sa mga sariling kakayahan na wala sa ibang nilalang (hal. kakayahang magpasiya, umunawa ng damdamin ng iba). - Nailalarawan ang mga katangian ng tao na nagpapabukod-tangi sa kaniya sa ibang nilalang.', 1, '1 to 2 (10 days)', NULL),
  ('GMRC', 4, 'G4-002', 'Naisasabuhay ang pagpapahalaga sa sarili sa pamamagitan ng pagbibigay-halaga sa mga sariling kakayahan na wala sa ibang nilalang (hal. kakayahang magpasiya, umunawa ng damdamin ng iba). - Naipaliliwanag na ang sariling kakayahang mag-isip at magmahal na natatangi sa tao ay magagamit niya upang mapabuti ang kaniyang mga gawi at pakikipag- ugnayan sa kapwa.', 1, '1 to 2 (10 days)', NULL),
  ('GMRC', 4, 'G4-003', 'Naisasabuhay ang pagpapahalaga sa sarili sa pamamagitan ng pagbibigay-halaga sa mga sariling kakayahan na wala sa ibang nilalang (hal. kakayahang magpasiya, umunawa ng damdamin ng iba). - Nakapag-aangkop ng mga kilos na nagpapakita ng kakayahang mag-isip at magmahal ng tao bilang bahagi ng kaniyang pagkabukod-tangi. matatag na samahan bilang tanda ng pagiging matapat.', 1, '1 to 2 (10 days)', NULL),
  ('GMRC', 4, 'G4-004', 'Nakapagsasanay sa pagiging matapat sa pamamagitan ng angkop na paglalahad ng tunay na saloobin sa mga kasapi ng pamilya. - Nakakikilala ng mga sariling gawi ng mabuting pakikitungo sa mga kasapi ng pamilya.', 1, '3 to 4 (10 days)', NULL),
  ('GMRC', 4, 'G4-005', 'Nakapagsasanay sa pagiging matapat sa pamamagitan ng angkop na paglalahad ng tunay na saloobin sa mga kasapi ng pamilya. - Napangangatuwiranan na ang mga sariling gawi ng mabuting pakikitungo sa mga kasapi ng pamilya ay tungkulin at pananagutan ng bawat isa tungo sa masaya at matatag na samahan.', 1, '3 to 4 (10 days)', NULL),
  ('GMRC', 4, 'G4-006', 'Nakapagsasanay sa pagiging matapat sa pamamagitan ng angkop na paglalahad ng tunay na saloobin sa mga kasapi ng pamilya. - Naisasakilos ang mga sariling gawi ng mabuting pakikitungo sa mga kasapi ng pamilya na nagpapanatili ng masaya at matatag na Samahan.', 1, '3 to 4 (10 days)', NULL),
  ('GMRC', 4, 'G4-007', 'Naisasabuhay ang pagiging magalang sa pamamagitan ng pakikilahok sa mga gawain na kumikilala sa karapatan ng kapuwa-bata. - Nailalahad ang sariling mga tungkulin sa pagkilala sa karapatan ng kapuwa-bata.', 1, '5 (5 days)', NULL),
  ('GMRC', 4, 'G4-008', 'Naisasabuhay ang pagiging magalang sa pamamagitan ng pakikilahok sa mga gawain na kumikilala sa karapatan ng kapuwa-bata. - Nakapagbibigay ng mga patunay na ang sariling tungkulin sa pagkilala sa karapatan ng kapuwa-bata ay mahalaga sa pagpapanatili ng kaayusan at kapayapaan.', 1, '5 (5 days)', NULL),
  ('GMRC', 4, 'G4-009', 'Naisasabuhay ang pagiging magalang sa pamamagitan ng pakikilahok sa mga gawain na kumikilala sa karapatan ng kapuwa-bata. - Naisasakilos ang mga tungkulin sa pagkilala sa mga karapatan ng kapuwa-bata.', 1, '5 (5 days)', NULL),
  ('GMRC', 4, 'G4-010', 'Naipakikita ang pananalig sa Diyos sa pamamagitan ng mga paraan ng pagsamba at pagsunod sa mga tagubilin ng kinabibilangang pananampalataya. - Nakapaghahayag ng mga mahalagang aral ng kinabibilangang pananampalataya.', 1, '6 to 7 (10 days)', NULL),
  ('GMRC', 4, 'G4-011', 'Naipakikita ang pananalig sa Diyos sa pamamagitan ng mga paraan ng pagsamba at pagsunod sa mga tagubilin ng kinabibilangang pananampalataya. - Naipaliliwanag na ang pagkilala sa sariling pananampalataya ay nagsisilbing gabay upang mas mapabuti ang mga kilos at mailapit ang sarili sa Diyos', 1, '6 to 7 (10 days)', NULL),
  ('GMRC', 4, 'G4-012', 'Naipakikita ang pananalig sa Diyos sa pamamagitan ng mga paraan ng pagsamba at pagsunod sa mga tagubilin ng kinabibilangang pananampalataya. - Naisasakilos ang mga aral ng kinabibilangang pananampalataya', 1, '6 to 7 (10 days)', NULL),
  ('GMRC', 4, 'G4-013', 'Naipakikita ang pagiging mapanagutan sa pamamagitan ng paglahok sa mga gawaing pangangalaga at pagpaparami ng mga puno at halaman. - Naiisa-isa ang mga sariling gawi sa pangangalaga sa mga puno at halaman.', 1, '8 to 9 (10 days)', NULL),
  ('GMRC', 4, 'G4-014', 'Naipakikita ang pagiging mapanagutan sa pamamagitan ng paglahok sa mga gawaing pangangalaga at pagpaparami ng mga puno at halaman. - Naipaliliwanag na ang mga sariling gawi sa pangangalaga sa mga puno at halaman ay dapat linangin sa bawat bata bilang bahagi ng kaniyang pagiging katiwala sa pagpapanatiling ligtas, malinis at maayos ang kapaligiran.', 1, '8 to 9 (10 days)', NULL),
  ('GMRC', 4, 'G4-015', 'Naipakikita ang pagiging mapanagutan sa pamamagitan ng paglahok sa mga gawaing pangangalaga at pagpaparami ng mga puno at halaman. - Naisasakilos ang mga sariling gawi sa pangangalaga sa mga puno at halaman.', 1, '8 to 9 (10 days)', NULL),
  ('GMRC', 4, 'G4-016', 'Nakapagsasanay ng pagmamahal sa bayan sa pamamagitan ng mga gawain na nagtatampok sa mga Pilipinong nagsasabuhay ng mabuting kaugalian. - Natutukoy ang mga pansariling taglay na mga mabuting kaugaliang Pilipino (hal. masayahin, madasalin, masipag).', 1, '10 to 11 (10 days)', NULL),
  ('GMRC', 4, 'G4-017', 'Nakapagsasanay ng pagmamahal sa bayan sa pamamagitan ng mga gawain na nagtatampok sa mga Pilipinong nagsasabuhay ng mabuting kaugalian. - Naipaliliwanag na ang sariling kamalayan sa mga mabuting kaugaliang Pilipino ay mahalaga upang maiangkop ang mga kilos at pag-iisip na katangi-tangi sa lahing pinagmulan.', 1, '10 to 11 (10 days)', NULL),
  ('GMRC', 4, 'G4-018', 'Nakapagsasanay ng pagmamahal sa bayan sa pamamagitan ng mga gawain na nagtatampok sa mga Pilipinong nagsasabuhay ng mabuting kaugalian. - Naisasakilos ang mga tinataglay na mabuting kaugaliang Pilipino.', 1, '10 to 11 (10 days)', NULL),
  ('GMRC', 4, 'G4-019', 'Naisasabuhay ang tiwala sa sarili sa pamamagitan ng paglahok sa mga programang pampaaralan na nagpapaunlad ng mga kakayahan, talento at hilig nang may paggabay ng pamilya. - Naiisa-isa ang mga sariling kakayahan, talento at hilig ng isang bata na kailangang paunlarin nang may paggabay ng pamilya.', 1, '12 to 13 (9 days)', NULL),
  ('GMRC', 4, 'G4-020', 'Naisasabuhay ang tiwala sa sarili sa pamamagitan ng paglahok sa mga programang pampaaralan na nagpapaunlad ng mga kakayahan, talento at hilig nang may paggabay ng pamilya. - Naipaliliwanag na ang pagpapaunlad ng sariling kakayahan, talento at hilig nang may paggabay ng pamilya ay nakapag-aangat ng tiwala sa sarili at kalooban upang gawin ang kaniyang mga tungkulin.', 1, '12 to 13 (9 days)', NULL),
  ('GMRC', 4, 'G4-021', 'Naisasabuhay ang tiwala sa sarili sa pamamagitan ng paglahok sa mga programang pampaaralan na nagpapaunlad ng mga kakayahan, talento at hilig nang may paggabay ng pamilya. - Nailalapat ang sariling pagpapaunlad ng mga sariling kakayahan, talento at hilig nang may paggabay ng pamilya.', 1, '12 to 13 (9 days)', NULL),
  ('GMRC', 4, 'G4-022', 'Nakapagsasanay sa pagiging matipid sa pamamagitan ng pagtatabi ng mga bahagi ng baong pera/allowance o gamit na ayon sa kakayahan na maaaring makatulong sa sarili o kapuwa sa panahon ng pangangailangan. - Naipahahayag ang ugnayan ng sariling pagtitipid at pag-iimpok sa pagtulong sa kapuwa', 2, '1 (5 days)', NULL),
  ('GMRC', 4, 'G4-023', 'Nakapagsasanay sa pagiging matipid sa pamamagitan ng pagtatabi ng mga bahagi ng baong pera/allowance o gamit na ayon sa kakayahan na maaaring makatulong sa sarili o kapuwa sa panahon ng pangangailangan. - Naipaliliwanag na ang pagtitipid at pag-iimpok para makatulong sa kapuwa ay mahalagang disiplinang pansarili na dapat linangin upang matugunan ang pangangailangan ng sarili at kapuwa sa takdang panahon.', 2, '1 (5 days)', NULL),
  ('GMRC', 4, 'G4-024', 'Nakapagsasanay sa pagiging matipid sa pamamagitan ng pagtatabi ng mga bahagi ng baong pera/allowance o gamit na ayon sa kakayahan na maaaring makatulong sa sarili o kapuwa sa panahon ng pangangailangan. - Nailalapat ang mga paraan ng pagtitipid at pag-iimpok na nakalaan para sa sarili at kapuwa. mapagpasalamat.', 2, '1 (5 days)', NULL),
  ('GMRC', 4, 'G4-025', 'Naisasabuhay ang pagiging mapagpasalamat sa pamamagitan ng paggamit sa mga kontribusyon ng mga natatanging taong may kapansanan o Persons with Disability (PWD) bilang gabay sa pasiya at kilos. - Nailalarawan ang mga katangi-tanging nagawa at pagpapahahalaga ng mga taong may kapansanan o Persons with Disability (PWD) sa pamayanang kinabibilangan.', 2, '2 to 3 (10 days)', NULL),
  ('GMRC', 4, 'G4-026', 'Naisasabuhay ang pagiging mapagpasalamat sa pamamagitan ng paggamit sa mga kontribusyon ng mga natatanging taong may kapansanan o Persons with Disability (PWD) bilang gabay sa pasiya at kilos. - Naipaliliwanag na ang sariling pagkilala sa mga natatanging taong may kapansanan o Persons with Disability (PWD) sa Pamayanan ay pagpapahalaga sa kanilang mga kontribusyon na nagpapabuti sa kalagayan ng lipunan o bayan.', 2, '2 to 3 (10 days)', NULL),
  ('GMRC', 4, 'G4-027', 'Naisasabuhay ang pagiging mapagpasalamat sa pamamagitan ng paggamit sa mga kontribusyon ng mga natatanging taong may kapansanan o Persons with Disability (PWD) bilang gabay sa pasiya at kilos. - Nakapaglalapat ng mga paraan upang bigyang pagkilala ang mga natatanging taong may kapansanan o Persons with Disability (PWD) dahil sa kanilang kontribusyon.', 2, '2 to 3 (10 days)', NULL),
  ('GMRC', 4, 'G4-028', 'Nakapagsasanay ng pagiging matiyaga sa pamamagitan ng palagiang paggawa ng mga gawaing bukas sa mungkahi ng miyembro ng pamilya. - Nakapaglalarawan ng mga aktibidad / pagkilos sa pamilya na kailangang gawin nang may kalidad.', 2, '4 (5 days)', NULL),
  ('GMRC', 4, 'G4-029', 'Nakapagsasanay ng pagiging matiyaga sa pamamagitan ng palagiang paggawa ng mga gawaing bukas sa mungkahi ng miyembro ng pamilya. - Naipaliliwanag na ang pagtupad sa mga gawain ay nakapagpapaunlad ng sarili at ugnayan sa pamilya.', 2, '4 (5 days)', NULL),
  ('GMRC', 4, 'G4-030', 'Nakapagsasanay ng pagiging matiyaga sa pamamagitan ng palagiang paggawa ng mga gawaing bukas sa mungkahi ng miyembro ng pamilya. - Nailalapat ang mga gawain sa pamilya na kailangang gawin nang may kalidad.', 2, '4 (5 days)', NULL),
  ('GMRC', 4, 'G4-031', 'Nakapagsasanay sa pagiging mapagpasensiya sa pamamagitan ng angkop na pananalita at pagtugon sa kapuwa nang may pagsasaalang-alang sa damdamin ng kapuwa. - Natutukoy ang mga aral na natutuhan mula sa pamilya kaugnay ng maayos na komunikasyon sa kapuwa.', 2, '5 (5 days)', NULL),
  ('GMRC', 4, 'G4-032', 'Nakapagsasanay sa pagiging mapagpasensiya sa pamamagitan ng angkop na pananalita at pagtugon sa kapuwa nang may pagsasaalang-alang sa damdamin ng kapuwa. - Naipaliliwanag na ang pamilya bilang pinagmumulan ng maayos na komunikasyon sa kapuwa ay nakapaglilinang ng mga angkop na gawi o pagtugon sa pakikipag-ugnayan ng mga kasapi nito sa ibang tao.', 2, '5 (5 days)', NULL),
  ('GMRC', 4, 'G4-033', 'Nakapagsasanay sa pagiging mapagpasensiya sa pamamagitan ng angkop na pananalita at pagtugon sa kapuwa nang may pagsasaalang-alang sa damdamin ng kapuwa. - Nailalapat ang mga natutuhan mula sa pamilya kaugnay ng maayos na komunikasyon sa kapuwa. tanda ng pagiging masunurin.', 2, '5 (5 days)', NULL),
  ('GMRC', 4, 'G4-034', 'Naipakikita ang pagiging masunurin sa pamamagitan ng mapagkalingang pakikitungo sa mga kasapi ng pamilya. - Nakapagpapahayag ng iba’t ibang paraan ng paglalapat ng mga aral ng pananampalataya sa mga sitwasyon sa pamilya.', 2, '6 to 7 (10 days)', NULL),
  ('GMRC', 4, 'G4-035', 'Naipakikita ang pagiging masunurin sa pamamagitan ng mapagkalingang pakikitungo sa mga kasapi ng pamilya. - Nakapagsusuri na ang paglalapat ng mga aral ng pananampalataya bilang gabay sa mga situwasyon sa pamilya ay tungo sa malugod na pamumuhay.', 2, '6 to 7 (10 days)', NULL),
  ('GMRC', 4, 'G4-036', 'Naipakikita ang pagiging masunurin sa pamamagitan ng mapagkalingang pakikitungo sa mga kasapi ng pamilya. - Naisasakilos ang iba’t ibang paraan ng paglalapat ng mga aral ng pananampalataya sa mga situwasyon sa pamilya.', 2, '6 to 7 (10 days)', NULL),
  ('GMRC', 4, 'G4-037', 'Napagsisikap sa pagiging mabuting katiwala sa pamamagitan ng paglahok sa mga gawain ng pamilya na nagpapanatili ng kalinisan ng tubig. - Natutukoy ang mga tungkulin ng pamilya sa pagpapanatili ng kalinisan ng tubig.', 2, '8 to 9 (10 days)', NULL),
  ('GMRC', 4, 'G4-038', 'Napagsisikap sa pagiging mabuting katiwala sa pamamagitan ng paglahok sa mga gawain ng pamilya na nagpapanatili ng kalinisan ng tubig. - Nabibigyang-diin na ang tungkulin ng pamilya sa pagpapanatili ng kalinisan ng tubig ay bahagi ng kanilang gampanin bilang katiwala na sinisiguradong may pagkukunan ng pangangailangan ang kasalukuyan at ang mga susunod na henerasyon.', 2, '8 to 9 (10 days)', NULL),
  ('GMRC', 4, 'G4-039', 'Napagsisikap sa pagiging mabuting katiwala sa pamamagitan ng paglahok sa mga gawain ng pamilya na nagpapanatili ng kalinisan ng tubig. - Nailalapat ang mga pansariling paraan bilang bahagi ng tungkulin ng pamilyang kinabibilangan sa pagpapanatili ng kalinisan ng tubig.', 2, '8 to 9 (10 days)', NULL),
  ('GMRC', 4, 'G4-040', 'Nakapagsasanay sa pagmamahal sa bayan sa pamamagitan ng pagtugon sa pagpapatatag ng mga gawi sa pamilya ayon sa kaugaliang Pilipino. - Nailalarawan ang mga kalagayan ng pagpapatatag ng mga gawi sa pamilya ayon sa kaugaliang Pilipino.', 2, '10 to 11 (10 days)', NULL),
  ('GMRC', 4, 'G4-041', 'Nakapagsasanay sa pagmamahal sa bayan sa pamamagitan ng pagtugon sa pagpapatatag ng mga gawi sa pamilya ayon sa kaugaliang Pilipino. - Naipaliliwanag na ang pagpapatatag sa mga gawi sa pamilya ayon sa kaugaliang Pilipino ay nagpapalakas ng damdaming makabayan.', 2, '10 to 11 (10 days)', NULL),
  ('GMRC', 4, 'G4-042', 'Nakapagsasanay sa pagmamahal sa bayan sa pamamagitan ng pagtugon sa pagpapatatag ng mga gawi sa pamilya ayon sa kaugaliang Pilipino. - Naisasakilos ang mga pakikilahok sa mga gawain na nagpapatatag ng mga kaugaliang Pilipino. mapagmalasakit.', 2, '10 to 11 (10 days)', NULL),
  ('GMRC', 4, 'G4-043', 'Naisasabuhay ang pagiging mapagmalasakit sa pamamagitan ng pakikiisa sa pamilya sa pagtugon sa pangangailangan ng kapuwa. - Nakapag-uuri ng mga tungkulin ng pamilya sa kapuwa (hal. pagiging bukas-palad sa mga nangangailangan, pakikiramay sa panahon ng krisis, pagtuturo sa mga batang walang magulang o tagapangalaga).', 2, '12 (5 days)', NULL),
  ('GMRC', 4, 'G4-044', 'Naisasabuhay ang pagiging mapagmalasakit sa pamamagitan ng pakikiisa sa pamilya sa pagtugon sa pangangailangan ng kapuwa. - Napatutunayan na ang pagtupad ng tungkulin ng pamilya sa kapuwa ay dapat gampanan bilang bahagi ng kanilang tungkulin na maglingkod sa kapuwa at mapagbuti ang kanilang ugnayan.', 2, '12 (5 days)', NULL),
  ('GMRC', 4, 'G4-045', 'Naisasabuhay ang pagiging mapagmalasakit sa pamamagitan ng pakikiisa sa pamilya sa pagtugon sa pangangailangan ng kapuwa. - Naisasakilos ang mga pansariling paraan sa pagtupad ng tungkulin ng pamilya sa kapuwa.', 2, '12 (5 days)', NULL),
  ('GMRC', 4, 'G4-046', 'Naisasabuhay ang pagiging magalang sa kapuwa sa pamamagitan ng pantay-pantay na pakikipag-ugnayan sa kabila ng pagkakaiba-iba (hal. walang pagtatangi sa kapuwa anuman ang kaniyang estado sa buhay). - Nakapaghahambing ng mga pagkakatulad at pagkakaiba-iba ng sarili at kapuwa.', 2, '13 (3 days)', NULL),
  ('GMRC', 4, 'G4-047', 'Naisasabuhay ang pagiging magalang sa kapuwa sa pamamagitan ng pantay-pantay na pakikipag-ugnayan sa kabila ng pagkakaiba-iba (hal. walang pagtatangi sa kapuwa anuman ang kaniyang estado sa buhay). - Naipaliliwanag na ang pagkakapantay-pantay ng bawat isa sa kabila ng pagkakaiba-iba ay patunay na lahat ay may karapatan at tungkulin na dapat kilalanin ng bawat isa tungo sa mapayapang ugnayan.', 2, '13 (3 days)', NULL),
  ('GMRC', 4, 'G4-048', 'Naisasabuhay ang pagiging magalang sa kapuwa sa pamamagitan ng pantay-pantay na pakikipag-ugnayan sa kabila ng pagkakaiba-iba (hal. walang pagtatangi sa kapuwa anuman ang kaniyang estado sa buhay). - Nakabubuo ng mga paraan upang itaguyod ang pagkapantay-pantay ng bawat isa sa kabila ng pagkakaiba-iba.', 2, '13 (3 days)', NULL),
  ('GMRC', 4, 'G4-049', 'Nakapagsasanay sa pagiging mapagpakumbaba sa pamamagitan ng regular na pananalangin, kusang pag- amin sa mga nagawang kamalian, at pagkilala na lahat ay magkakapantay-pantay o walang nakahihigit sa isa’t isa. - Nakapagpapahayag ng mga aral ng kababaang-loob sa kapuwa mula sa kinabibilangang pananampalataya.', 3, '1 to 2 (10 days)', NULL),
  ('GMRC', 4, 'G4-050', 'Nakapagsasanay sa pagiging mapagpakumbaba sa pamamagitan ng regular na pananalangin, kusang pag- amin sa mga nagawang kamalian, at pagkilala na lahat ay magkakapantay-pantay o walang nakahihigit sa isa’t isa. - Naipaliliwanag na ang kababaang-loob sa kapuwa bilang tanda ng pananampalataya ay nakatutulong sa pagpapabuti ng kanilang ugnayan tungo sa paglilingkod sa iba.', 3, '1 to 2 (10 days)', NULL),
  ('GMRC', 4, 'G4-051', 'Nakapagsasanay sa pagiging mapagpakumbaba sa pamamagitan ng regular na pananalangin, kusang pag- amin sa mga nagawang kamalian, at pagkilala na lahat ay magkakapantay-pantay o walang nakahihigit sa isa’t isa. - Naisasakilos ang mga aral ng kababaang-loob sa kapuwa mula sa kinabibilangang pananampalataya. tanda ng pagiging malinis.', 3, '1 to 2 (10 days)', NULL),
  ('GMRC', 4, 'G4-052', 'Naipakikita ang kalinisan sa pamamagitan ng palagiang pagpapaalala sa kapuwa-bata ng wastong pagpapanatili ng kaayusan at kalinisan ng kapaligiran - Naiisa-isa ang mga gawaing pangkapaligiran na kasama ang kapuwa', 3, '3 (5 days)', NULL),
  ('GMRC', 4, 'G4-053', 'Naipakikita ang kalinisan sa pamamagitan ng palagiang pagpapaalala sa kapuwa-bata ng wastong pagpapanatili ng kaayusan at kalinisan ng kapaligiran - Naiuugnay na ang mga gawaing pangkapaligiran kasama ang kapuwa ay nakapagpapagaan ng mga tungkuling panatilihin ang kaayusan nito', 3, '3 (5 days)', NULL),
